begin;
select plan(11);
insert into auth.users(id,instance_id,aud,role,email,created_at,updated_at) values('00000000-0000-0000-0000-000000000101','00000000-0000-0000-0000-000000000000','authenticated','authenticated','matthewirving99@gmail.com',now(),now()) on conflict(id) do nothing;
insert into public.app_users(id,email,is_allowed) values('00000000-0000-0000-0000-000000000101','matthewirving99@gmail.com',true) on conflict(id) do update set is_allowed=true;
insert into public.worker_devices(id,user_id,label,public_key_b64,state,paired_at,worker_secret_hash) values('41000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000101','Synthetic revoke fixture','ai41-synthetic-public-key','online',now(),repeat('a',64)),('41000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000101','Other synthetic worker','ai41-other-public-key','online',now(),repeat('b',64));
insert into public.digital_scans(id,user_id,device_id,scan_kind,approved_roots,status) select ('41000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000101','41000000-0000-4000-8000-000000000001','lightweight','["C:\\synthetic"]',s from (values(11,'queued'),(12,'waiting_for_device'),(13,'running'),(14,'complete')) as x(n,s);
insert into public.digital_scans(id,user_id,device_id,scan_kind,approved_roots,status) values('41000000-0000-4000-8000-000000000015','00000000-0000-0000-0000-000000000101','41000000-0000-4000-8000-000000000002','lightweight','["C:\\synthetic"]','running');
insert into public.workflow_runs(id,user_id,workflow_definition_id,status,trigger,idempotency_key) select '41000000-0000-4000-8000-000000000030','00000000-0000-0000-0000-000000000101',id,'queued','manual','ai41-revoke-synthetic-run' from public.workflow_definitions where code='digital-estate-lightweight';
update public.digital_scans set run_id='41000000-0000-4000-8000-000000000030' where id='41000000-0000-4000-8000-000000000013';
insert into public.mfa_action_gates(id,user_id,action_key,expires_at) values('41000000-0000-4000-8000-000000000020','00000000-0000-0000-0000-000000000101','worker_device_revoke',now()+interval '2 minutes');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000101","role":"authenticated","aal":"aal2"}',true);
select is(public.revoke_worker_device_from_mfa_gate('41000000-0000-4000-8000-000000000001','41000000-0000-4000-8000-000000000020')->>'status','revoked','fresh gate revokes worker');
select is((select count(*)::integer from public.digital_scans where device_id='41000000-0000-4000-8000-000000000001' and status='cancelled'),3,'all outstanding scans terminalize on revoke');
select ok((select bool_and(completed_at is not null) from public.digital_scans where device_id='41000000-0000-4000-8000-000000000001' and status='cancelled'),'cancelled scans carry terminal timestamp');
select is((select status from public.digital_scans where id='41000000-0000-4000-8000-000000000014'),'complete','completed evidence preserved');
select is((select status from public.digital_scans where id='41000000-0000-4000-8000-000000000015'),'running','another device work unaffected');
select ok((select worker_secret_hash is null from public.worker_devices where id='41000000-0000-4000-8000-000000000001'),'old secret invalidated');
select is(public.revoke_worker_device_from_mfa_gate('41000000-0000-4000-8000-000000000001','41000000-0000-4000-8000-000000000020')->>'code','mfa_gate_replayed','gate replay denied');
select is((select count(*)::integer from public.audit_events where target_id='41000000-0000-4000-8000-000000000001' and action_type='worker_device_revoked'),1,'one revocation audit');
select is((select status::text from public.workflow_runs where id='41000000-0000-4000-8000-000000000030'),'cancelled','device-owned queued workflow terminalizes using canonical cancellation');
select ok((select cancelled_at is not null and completed_at is not null from public.workflow_runs where id='41000000-0000-4000-8000-000000000030'),'workflow carries terminal timestamps');
select is((select count(*)::integer from public.trace_events where correlation_id=(select correlation_id from public.workflow_runs where id='41000000-0000-4000-8000-000000000030') and event_type='run_cancelled'),1,'canonical cancellation emits correlated trace');
select * from finish();rollback;
